using EncoDeck.Core.Capabilities;
using EncoDeck.Core.Profiles;
using EncoDeck.Core.State;

namespace EncoDeck.Protocol.Oppo.Models;

/// <summary>
/// Turns the official client's per-model configuration (<see cref="Models"/>, generated by
/// tools/assets/make_models.py) into <see cref="OppoModelDefinition"/>s, reading every field the
/// way the official client does (see docs/PROTOCOL_FINDINGS.md §9). The hand-made Enco X4
/// definition is the reference: its catalog entry converts to the same protocol values (tested).
/// </summary>
internal static partial class OppoCatalog
{
    private const string Official = "Official client configuration";

    /// <summary>Gesture function offered for each <c>support</c> bit, in the official display order.</summary>
    private static readonly (int Bit, int Function)[] SupportBits =
    [
        (1 << 9, 0), (1 << 7, 8), (1 << 2, 1), (1 << 5, 5), (1 << 6, 6), (1 << 0, 3), (1 << 3, 11), (1 << 4, 12),
        (1 << 10, 7), (1 << 11, 10), (1 << 12, 13), (1 << 13, 17), (1 << 15, 22), (1 << 16, 18), (1 << 18, 28), (1 << 19, 29),
    ];
    // Not offered on a PC: 2 "open music" (shown as none), 8 play favourites (phone app), 14 pairing and
    // 22 clear history (no wire id), 17 AI summary, 20/21 translation, 23 "spy tap", 24/25 Gemini.

    /// <summary>Long-press functions (<c>longPressType</c> bits) in the official order: none, noise control, voice assistant, game mode.</summary>
    private static readonly (int Bit, int Function)[] LongPressBits = [(1 << 9, 0), (1 << 7, 8), (1 << 0, 3), (1 << 13, 17)];

    private const int AiSummaryBit = 1 << 17;
    private const int ZenBit = 1 << 16;

    /// <summary>Config actions that are fixed descriptions, never written.</summary>
    private static readonly HashSet<int> InfoActions = [7, 8, 12, 13, 14, 15];

    /// <summary>Config actions whose row edits the long-press noise cycle.</summary>
    private static readonly HashSet<int> NoiseCycleActions = [11, 20, 25, 27];

    private static readonly Lazy<OppoModelDefinition[]> LazyDefinitions = new(() =>
        [.. Models.Concat(SupplementModels).Concat(RealmeExtraModels).Select(WithRealmeFacts).Select(ToDefinition)]);

    // Lazy: the generated Models list lives in another part of this class, whose static
    // initializers may run after this one.
    public static IReadOnlyList<OppoModelDefinition> Definitions => LazyDefinitions.Value;

    public static OppoModelDefinition ToDefinition(CatalogModel model)
    {
        var capabilities = DeviceCapabilities.CreateBuilder()
            .Set(DeviceCapability.BatteryLevel, CapabilitySupport.Supported, "Shared OPPO battery query 0x0106.")
            .Set(DeviceCapability.ChargingStatus, CapabilitySupport.Supported, "Shared OPPO battery query 0x0106.")
            .Set(DeviceCapability.FirmwareInformation, CapabilitySupport.Supported, "Shared OPPO version query 0x0105.");
        void Offer(DeviceCapability capability, string evidence) => capabilities.Set(capability, CapabilitySupport.Supported, $"{Official}: {evidence}");

        var (noiseModes, parents, cycleLabels) = Noise(model);
        if (noiseModes.Count > 0)
        {
            Offer(DeviceCapability.NoiseCancellation, "noise-control tree, 0x0404 / 0x010C.");
            if (noiseModes.Any(m => m.Option.Mode == NoiseControlMode.NoiseCancellation && m.Option.LevelId is not null)) Offer(DeviceCapability.NoiseCancellationLevel, "noise-cancelling levels.");
            if (noiseModes.Any(m => m.Option.Mode == NoiseControlMode.Adaptive)) Offer(DeviceCapability.AdaptiveNoiseCancellation, "adaptive noise cancelling.");
        }

        var (presets, presetFirmware) = Equalizer(model);
        if (presets.Count > 0) Offer(DeviceCapability.Equalizer, "EQ presets, 0x0406 + 0x010F.");
        ApplyRealmeConfidence(model, capabilities, noiseModes.Count > 0, presets.Count > 0);

        OppoCustomEqualizerSpec? customEq = null;
        if (model.Flag("customEqualizer") == 1)
        {
            var bands = model.List("customEqFrequency") is { Count: > 0 } list ? list : [62, 250, 1000, 4000, 8000, 16000];
            customEq = new OppoCustomEqualizerSpec(bands, -6, 6, model.Flags.TryGetValue("customEqMax", out int max) ? max : 3);
            Offer(DeviceCapability.CustomEqualizer, "custom EQ, 0x0418 + 0x0122.");
        }

        var switches = new List<OppoFeatureSwitch>();
        void Switch(DeviceToggle toggle, byte id) => switches.Add(new OppoFeatureSwitch(toggle, id, CapabilitySupport.Supported));

        var gameSoundTypes = model.GameSoundTypes;
        bool gameMode = model.Flag("gameMode") == 1 || model.Has("gameModeList");
        if (gameSoundTypes.Count > 0)
        {
            // Game page: master switch 40, low latency 6, game sound 0x0423.
            Switch(DeviceToggle.GamingMode, 0x28);
            Switch(DeviceToggle.LowLatency, 0x06);
            Offer(DeviceCapability.GamingMode, "game mode 40, low latency 6, game sound 0x0423.");
        }
        else if (gameMode)
        {
            // Single game-mode switch (feature 6); becomes the game page when the earbuds offer 0x0423 (see Adapt).
            Switch(DeviceToggle.GamingMode, 0x06);
            Offer(DeviceCapability.GamingMode, "game mode feature 6.");
        }
        if (model.Flag("wearDetection") is 1 or 2)
        {
            Switch(DeviceToggle.InEarDetection, 0x04);
            Offer(DeviceCapability.InEarDetection, "wear detection feature 4.");
        }
        if (model.Flag("multiDevicesConnect") is 1 or 2)
        {
            Switch(DeviceToggle.DualDeviceConnection, 0x11);
            Offer(DeviceCapability.DualDeviceConnection, "feature 17, 0x0112, 0x0429, 0x0132.");
        }
        if (model.Flag("sleepDetection") == 1) Switch(DeviceToggle.SleepDetection, 0x3A);
        if (model.Flag("swiftPair") == 1) Switch(DeviceToggle.SwiftPair, 0x37);
        if (model.Flag("voiceCommand") is 1 or 2) Switch(DeviceToggle.VoiceCommands, 0x19);
        if (model.Flag("headMotion") == 1) Switch(DeviceToggle.HeadGestures, 0x3B);
        if (model.Flag("bassEngineSupport") == 1)
        {
            Switch(DeviceToggle.BassEngine, 0x1D);
            Offer(DeviceCapability.BassEngine, "feature 29, 0x0124 / 0x041B.");
        }
        if (model.Flag("highToneQuality") is 1 or 2) Switch(DeviceToggle.HiRes, 0x18);
        if (model.Flag("controlAutoVolumeSupport") == 1) Switch(DeviceToggle.AutoVolume, 0x1C);

        var spatialTypes = model.List("spatialTypes");
        if (spatialTypes.Count > 0)
        {
            // V1 (feature 27) unless the earbuds offer 0x0422 (see Adapt).
            Switch(DeviceToggle.SpatialAudio, 0x1B);
            Offer(DeviceCapability.SpatialAudio, "spatial audio, 0x0422 / 0x012A or feature 27.");
            if (spatialTypes.Contains(2)) Offer(DeviceCapability.HeadTracking, "spatial mode 2 (follow head).");
        }

        if (model.Has("heyFindDevice") || model.Has("findDevice")) Offer(DeviceCapability.FindMyEarbuds, "0x0400 start/stop.");
        if (model.Flag("fitDetection") == 1) Offer(DeviceCapability.FitTest, "0x0405 + event 04.");
        if (model.Flag("promptVolume") == 1) Offer(DeviceCapability.PromptVolume, "0x0130 / 0x0427.");

        var gestures = Gestures(model);
        if (gestures.Any(g => g.IsWritten)) Offer(DeviceCapability.TouchCustomization, "0x0401 + 0x0108.");
        bool hasCycleRow = gestures.Any(g => g.EditsNoiseCycle);
        int longPressType = model.Flag("longPressType");
        int cycleMinimum = model.Controls.FirstOrDefault(c => NoiseCycleActions.Contains(c.Action))?.MinSelectCount is > 0 and var min
            ? min
            : model.Brand.Equals("OnePlus", StringComparison.OrdinalIgnoreCase) || longPressType > 0 ? 2 : 1;

        bool oldOnePlusBuds = model.Names[0] is "OnePlus Buds" or "OnePlus Buds Z";
        return new OppoModelDefinition
        {
            ModelId = "oppo-" + model.ProductId.ToLowerInvariant(),
            SupportsLeAudioPairing = model.ProductIdValue is 0x067410 or 0x06EC10,
            DisplayName = model.Name,
            ImageKey = "generic",
            // "N" is the official configuration's neckband type.
            Form = model.Type == "N" ? DeviceForm.Headphones : DeviceForm.Earbuds,
            ProductIds = [model.ProductIdValue],
            BluetoothNames = model.Names,
            // The official client uses the configured UUID, 00001107-… when none is set.
            // (the other candidate stays as a fallback for firmware that moved it).
            ServiceUuids = ServiceUuids(model.Uuid),
            Capabilities = capabilities.Build(),
            NoiseModes = noiseModes,
            NoiseModeParents = parents,
            NoiseCycleIndices = hasCycleRow ? [.. cycleLabels.Keys] : [],
            NoiseCycleLabels = cycleLabels,
            NoiseCycleShared = longPressType == 0,
            NoiseCycleMinimum = cycleMinimum,
            EqualizerPresets = presets,
            EqualizerMinFirmware = presetFirmware,
            CustomEqualizer = customEq,
            FeatureSwitches = switches,
            FeatureStatusIds = StatusIds(model),
            GestureRows = gestures,
            GameSoundTypes = gameSoundTypes,
            SpatialTypes = spatialTypes,
            SpatialHiResMutex = model.Flag("spatialHiResMutex") == 1,
            PromptVolumeRange = model.PromptVolumeRange ?? (1, 10),
            TimeReplyIncludesOffset = model.Flag("utcTimeZone") == 1,
            // The official "OnePlus Buds" / "Buds Z" use 4 and 5 for previous and next.
            FunctionLabels = oldOnePlusBuds ? new Dictionary<int, string> { [4] = "Function_5", [5] = "Function_6" } : new Dictionary<int, string>(),
        };
    }

    private static Guid[] ServiceUuids(string configured)
    {
        var uuid = string.IsNullOrEmpty(configured) ? OppoServiceUuids.Primary : Guid.Parse(configured);
        return [uuid, .. OppoServiceUuids.Candidates.Where(c => c != uuid)];
    }

    // ---- noise control -------------------------------------------------------------------------

    private static (List<OppoNoiseMode> Modes, Dictionary<NoiseControlMode, OppoNoiseParent> Parents, Dictionary<int, string> CycleLabels) Noise(CatalogModel model)
    {
        var modes = new List<OppoNoiseMode>();
        var parents = new Dictionary<NoiseControlMode, OppoNoiseParent>();
        // Extra report indices that mean "transparency" (voice listening, enhance-voices on).
        var transparencyAliases = new List<int>();

        void Level(NoiseControlMode mode, string id, string label, string key, int index, params int[] alsoReported) =>
            modes.Add(new OppoNoiseMode(new NoiseControlOption(mode, id, label, key, CapabilitySupport.Supported), index, [index, .. alsoReported]));
        void Single(NoiseControlMode mode, string label, string key, CatalogNoiseNode node)
        {
            // Top-level button: sends the node's own index; any child index is reported for it too.
            modes.Add(new OppoNoiseMode(new NoiseControlOption(mode, null, label, key, CapabilitySupport.Supported), node.ProtocolIndex,
                [.. node.Children.Select(c => c.ProtocolIndex), node.ProtocolIndex]));
            parents[mode] = new OppoNoiseParent(node.ProtocolIndex, CapabilitySupport.Supported);
        }

        foreach (var node in model.Noise)
        {
            switch (node.ModeType)
            {
                case 1:
                    Single(NoiseControlMode.Off, "Off", "NoiseMode_Off", node);
                    break;
                case 2:
                    // Children: plain transparency and, on X2/X3, "enhance voices" (modeType 6).
                    if (model.ProductIdValue == 0x067410 && node.Children.Any(c => c.ModeType == 6))
                    {
                        parents[NoiseControlMode.Transparency] = new(node.ProtocolIndex, CapabilitySupport.Supported, "transparency-standard");
                        foreach (var child in node.Children)
                        {
                            if (child.ModeType == 2)
                                Level(NoiseControlMode.Transparency, "transparency-standard", "Standard", "NoiseLevel_TransparencyStandard", child.ProtocolIndex, node.ProtocolIndex);
                            else if (child.ModeType == 6)
                                Level(NoiseControlMode.Transparency, "enhanced-voices", "Enhance voices", "NoiseLevel_EnhancedVoices", child.ProtocolIndex);
                        }
                    }
                    else Single(NoiseControlMode.Transparency, "Transparency", "NoiseMode_Transparency", node);
                    break;
                case 6:
                    // "Voice" listening (flat trees): shown by the official client only when the earbuds offer it.
                    transparencyAliases.Add(node.ProtocolIndex);
                    break;
                case 5 when node.Children.Count == 0:
                    Single(NoiseControlMode.NoiseCancellation, "Noise cancelling", "NoiseMode_NoiseCancellation", node);
                    break;
                case 5:
                    parents[NoiseControlMode.NoiseCancellation] = new OppoNoiseParent(node.ProtocolIndex, CapabilitySupport.Supported);
                    foreach (var child in node.Children)
                    {
                        switch (child.ModeType)
                        {
                            case 7: Level(NoiseControlMode.NoiseCancellation, "smart", "Auto", "NoiseLevel_Smart", child.ProtocolIndex); break;
                            case 4: Level(NoiseControlMode.NoiseCancellation, "deep", "High", "NoiseLevel_Deep", child.ProtocolIndex); break;
                            case 8: Level(NoiseControlMode.NoiseCancellation, "medium", "Moderate", "NoiseLevel_Medium", child.ProtocolIndex); break;
                            case 3: Level(NoiseControlMode.NoiseCancellation, "light", "Low", "NoiseLevel_Light", child.ProtocolIndex); break;
                        }
                    }
                    break;
                // Flat trees: strong, weak and smart noise cancelling are top-level buttons.
                case 4:
                    Level(NoiseControlMode.NoiseCancellation, "deep", "Max noise cancellation", "NoiseLevel_Strong", node.ProtocolIndex);
                    break;
                case 3:
                    Level(NoiseControlMode.NoiseCancellation, "light", "Noise cancellation", "NoiseLevel_Weak", node.ProtocolIndex);
                    break;
                case 7:
                    Level(NoiseControlMode.NoiseCancellation, "smart", "Smart", "NoiseLevel_SmartTop", node.ProtocolIndex);
                    break;
                case 10 when node.Children.Count == 0:
                    Single(NoiseControlMode.Adaptive, "Adaptive", "NoiseMode_Adaptive", node);
                    break;
                case 10:
                    string defaultLevel = node.Children.Any(c => c.ModeType == 12) ? "standard" : node.Children[0].ModeType switch { 11 => "less", 13 => "more", _ => "standard" };
                    parents[NoiseControlMode.Adaptive] = new OppoNoiseParent(node.ProtocolIndex, CapabilitySupport.Supported, DefaultLevelId: defaultLevel);
                    foreach (var child in node.Children)
                    {
                        var (id, label, key) = child.ModeType switch
                        {
                            11 => ("less", "Less noise", "NoiseLevel_AdaptiveLess"),
                            13 => ("more", "More noise", "NoiseLevel_AdaptiveMore"),
                            _ => ("standard", "Standard", "NoiseLevel_AdaptiveStandard"),
                        };
                        // A report of the parent index shows the default range (official summary fallback: standard).
                        if (id == defaultLevel) Level(NoiseControlMode.Adaptive, id, label, key, child.ProtocolIndex, node.ProtocolIndex);
                        else Level(NoiseControlMode.Adaptive, id, label, key, child.ProtocolIndex);
                    }
                    break;
            }
        }

        if (transparencyAliases.Count > 0 && modes.FirstOrDefault(m => m.Option.Mode == NoiseControlMode.Transparency) is { } transparency)
        {
            modes[modes.IndexOf(transparency)] = transparency with { ReportedIndices = [.. transparency.ReportedIndices, .. transparencyAliases] };
        }

        // Flat trees have no parent index for noise cancelling: choosing the mode selects its first level.
        if (!parents.ContainsKey(NoiseControlMode.NoiseCancellation)
            && modes.FirstOrDefault(m => m.Option.Mode == NoiseControlMode.NoiseCancellation && m.Option.LevelId is not null) is { } first)
        {
            parents[NoiseControlMode.NoiseCancellation] = new OppoNoiseParent(first.SetIndex, CapabilitySupport.Unsupported, DefaultLevelId: first.Option.LevelId);
        }

        // Long-press cycle: top-level modes in the official order (decided-by-device modes left out).
        int[] order = model.Flag("noiseReductionUIVersion") == 2 ? [4, 3, 5, 7, 10, 2, 6, 1] : [4, 3, 5, 7, 10, 1, 2, 6];
        var cycle = new Dictionary<int, string>();
        foreach (int type in order)
        {
            foreach (var node in model.Noise.Where(n => n.ModeType == type && !n.DecidedByDevice))
            {
                cycle[node.ProtocolIndex] = type switch
                {
                    1 => "NoiseMode_Off",
                    2 => "NoiseMode_Transparency",
                    3 => "NoiseLevel_Weak",
                    4 => "NoiseLevel_Strong",
                    5 => "NoiseMode_NoiseCancellation",
                    6 => "NoiseMode_Voice",
                    7 => "NoiseLevel_SmartTop",
                    _ => "NoiseMode_Adaptive",
                };
            }
        }
        return (modes, parents, cycle);
    }

    // ---- EQ ------------------------------------------------------------------------------------

    private static (Dictionary<byte, EqualizerPreset> Presets, Dictionary<byte, int> MinFirmware) Equalizer(CatalogModel model)
    {
        // Official list: compat, then by-version, then the base list; stable-sorted by order.
        var entries = model.EqualizerCompat.Concat(model.EqualizerByVersion).Concat(model.Equalizer)
            .Select((e, i) => (Entry: e, Index: i))
            .OrderBy(x => x.Entry.Order).ThenBy(x => x.Index)
            .Select(x => x.Entry);

        // Classic / bass / vocals have other names on some models (official rule).
        bool altNames = model.Flag("equalizer") == 2 || model.Name is "OPPO Enco R" or "OPPO Enco Air2";
        var presets = new Dictionary<byte, EqualizerPreset>();
        var firmware = new Dictionary<byte, int>();
        foreach (var entry in entries)
        {
            byte index = (byte)entry.ProtocolIndex;
            if (presets.ContainsKey(index) || EqualizerName(entry.ModeType, altNames, model.Name) is not { } name) continue;
            presets[index] = new EqualizerPreset($"eq-{entry.ModeType}", name.English, name.Key, CapabilitySupport.Supported);
            if (entry.MinFirmware > 0) firmware[index] = entry.MinFirmware;
        }
        return (presets, firmware);
    }

    private static (string Key, string English)? EqualizerName(int modeType, bool altNames, string modelName) => modeType switch
    {
        1 => altNames ? ("Eq_Mode1Alt", "Nature Balance") : ("Eq_Mode1", "Classic"),
        2 => altNames ? ("Eq_Mode2Alt", "Bass boost") : ("Eq_Mode2", "Dynamic bass"),
        3 => altNames ? ("Eq_Mode3Alt", "Clear vocals") : ("Eq_Mode3", "Clear vocals"),
        4 => modelName == "OPPO Enco R" ? ("Eq_Mode4Alt", "Gentle") : ("Eq_Mode4", "Clear"),
        42 => ("Eq_DynaudioOriginal", "Dynaudio original sound"),
        43 => ("Eq_DynaudioHiRes", "Dynaudio high-resolution"),
        28 => ("Eq_PureVocals", "Pure vocals"),
        46 => ("Eq_CrispHighs", "Crisp highs"),
        29 => ("Eq_ThunderingBass", "Thundering bass"),
        // realme built-ins (see OppoCatalog.Realme.cs).
        RealmeEqPureRaw => ("Eq_RealmePureRaw", "Pure Raw"),
        RealmeEqDeepBass => ("Eq_RealmeDeepBass", "Deep Bass"),
        RealmeEqPureVoice => ("Eq_PureVocals", "Pure vocals"),
        RealmeEqPureBass => ("Eq_RealmePureBass", "Pure Bass"),
        >= 5 and <= 22 or >= 25 and <= 27 or >= 30 and <= 35 or 40 or 41 => ($"Eq_Mode{modeType}", $"Preset {modeType}"),
        _ => null,
    };

    // ---- gestures ------------------------------------------------------------------------------

    private static List<OppoGestureRow> Gestures(CatalogModel model)
    {
        var rows = new List<OppoGestureRow>();
        int zenMode = model.Flag("zenMode");
        int longPressType = model.Flag("longPressType");

        foreach (var entry in model.Controls)
        {
            if (InfoActions.Contains(entry.Action)) continue;
            if (NoiseCycleActions.Contains(entry.Action))
            {
                if (model.Noise.Count == 0) continue;
                int[] functions = [.. LongPressBits.Where(b => (longPressType & b.Bit) != 0).Select(b => b.Function)];
                rows.Add(new OppoGestureRow(WireAction(entry.Action), false, functions, ControlLabel(entry.Action))
                {
                    BothEars = entry.ShowEar == 1,
                    EditsNoiseCycle = true,
                });
                continue;
            }
            int support = entry.Support;
            // Official: on triple rows Zen is not offered for zenMode 3.
            if (entry.Action is 3 or 18 && zenMode == 3) support &= ~ZenBit;
            // Long-press volume models adjust volume on hold through their own page.
            if (entry.Action == 4 && model.Flag("longPressVolume") == 1) continue;
            if (Functions(support) is not { Count: > 0 } allowed) continue;
            rows.Add(new OppoGestureRow(WireAction(entry.Action), false, allowed, ControlLabel(entry.Action))
            {
                BothEars = entry.ShowEar == 1,
                DefaultFunction = DefaultFunction(entry.DefaultFunction),
            });
        }

        foreach (var entry in model.CallControls)
        {
            // Official: call rows that offer AI summary (a phone feature) are not shown.
            if (entry.Action is 30 or 34 && (entry.Support & AiSummaryBit) != 0) continue;
            if (Functions(entry.Support) is not { Count: > 0 } allowed) continue;
            bool callButton = entry.Action >= 28;
            rows.Add(new OppoGestureRow(WireAction(entry.Action), true, allowed, CallLabel(entry.Action))
            {
                Button = callButton ? KeyFunction.CallButton : 1,
                BothEars = true,
                DefaultFunction = DefaultFunction(entry.DefaultFunction),
            });
        }
        return rows;
    }

    private static List<int> Functions(int support) => [.. SupportBits.Where(b => (support & b.Bit) != 0).Select(b => b.Function)];

    private static int? DefaultFunction(int bit) => SupportBits.Where(b => b.Bit == bit).Select(b => (int?)b.Function).FirstOrDefault();

    /// <summary>Wire action byte for a config action (official mapping; others pass through).</summary>
    internal static GestureAction WireAction(int action) => (GestureAction)(action switch
    {
        11 or 19 or 20 or 27 => 4,
        16 or 28 or 32 => 1,
        17 or 26 or 29 or 33 or 36 => 2,
        18 or 30 or 34 => 3,
        22 or 31 or 35 => 6,
        _ => action,
    });

    private static string ControlLabel(int action) => action switch
    {
        1 => "Gesture_Tap1",
        2 => "Gesture_Tap2",
        3 => "Gesture_Tap3",
        4 or 11 or 27 => "Gesture_TapHold",
        5 => "Gesture_Slide",
        6 => "Gesture_TapLongHold",
        16 => "Gesture_Single",
        17 => "Gesture_Double",
        18 => "Gesture_Triple",
        19 or 20 => "Gesture_Hold",
        22 => "Gesture_LongHold",
        25 => "Gesture_ButtonHold",
        26 => "Gesture_ButtonDouble",
        _ => "Gesture_Other",
    };

    private static string CallLabel(int action) => action switch
    {
        1 or 36 => "Gesture_CallButton",
        4 or 37 => "Gesture_CallButtonHold",
        28 => "Gesture_CallTap1",
        29 => "Gesture_CallTap2",
        30 => "Gesture_CallTap3",
        31 => "Gesture_CallTapLongHold",
        32 => "Gesture_CallSingle",
        33 => "Gesture_CallDouble",
        34 => "Gesture_CallTriple",
        35 => "Gesture_CallLongHold",
        _ => "Gesture_Other",
    };

    // ---- session -------------------------------------------------------------------------------

    /// <summary>The official session-start 0x010D query, built from the configuration in the official order.</summary>
    internal static List<byte> StatusIds(CatalogModel m)
    {
        var ids = new List<byte> { 0x05 };
        void If(bool condition, params byte[] add) { if (condition) ids.AddRange(add); }
        If(m.Flag("wearDetection") is 1 or 2, 0x04);
        If(m.Flag("hearingEnhancement") == 1 || m.Flag("hearingEnhancementNew") == 1, 0x0B);
        If(m.Flag("personalNoise") == 1 || m.Has("personalNoiseCompat"), 0x0C);
        If(m.Flag("clickTakePic") == 1 || m.Flag("clickTakePicNew") == 1, 0x0D);
        If(m.Flag("zenMode") > 0, 0x0F);
        If(m.Flag("multiDevicesConnect") is 1 or 2, 0x11);
        If(m.Flag("vocalEnhance") == 1, 0x09);
        If(m.Flag("headSetSoundRecord") == 1, 0x13);
        If(m.Flag("highToneQuality") is 1 or 2, 0x18);
        If(m.Flag("longPowerMode") == 1, 0x17);
        If(m.Flag("smartCall") == 1, 0x15);
        If(m.Flag("deviceLostRemind") == 1, 0x16);
        If(m.Flag("voiceWake") is 1 or 3, 0x14);
        If(m.Flag("voiceCommand") is 1 or 2, 0x19);
        If(m.Flag("gameMode") == 1 || m.Has("gameModeList"), 0x06);
        If(m.List("spatialTypes").Count > 0, 0x1B);
        If(m.Flag("bassEngineSupport") == 1, 0x1D);
        If(m.Flag("controlAutoVolumeSupport") == 1, 0x1C);
        If(m.Flag("collectLogs") == 1, 0x1E);
        If(m.Has("gameEqPkgList"), 0x21);
        // 0x1F (LE transport) is not a user toggle: the controller reports it on LE Audio links.
        If(m.Flag("spineHealth") is 1 or 2, 0x22, 0x23, 0x24);
        If(m.Flag("spineHealth") == 2, 0x3C);
        If(m.GameSoundTypes.Count > 0, 0x27, 0x28);
        If(m.Flag("adaptiveVolume") == 1, 0x30);
        If(m.Flag("adaptiveEar") == 1, 0x31);
        If(m.Flag("speechPerception") == 1, 0x32);
        If(m.Flag("meetingAssistant") == 1, 0x34);
        If(m.Flag("longPressVolume") == 1, 0x35);
        If(m.Flag("swiftPair") == 1, 0x37);
        If(m.Flag("hearingOptimize") == 1, 0x38);
        If(m.Flag("incomingCallControl") == 1, 0x39);
        If(m.Flag("headMotion") == 1, 0x3B);
        If(m.Flag("gmnVoiceAssist") is 1 or 2, 0x3D);
        If(m.Flag("sleepDetection") == 1, 0x3A);
        return ids;
    }
}
